void mainImage( out vec4 fragColor, in vec2 fragCoord )
{
/* Edge Detect Matrix */
    vec3 imageKernel[3];
    imageKernel[0] = vec3(0.0, -1.0, 0.0);
    imageKernel[1] = vec3(-1.0, 4.0, -1.0);
    imageKernel[2] = vec3(0.0, -1.0, 0.0);

    vec2 uv = fragCoord / iResolution.xy;
    vec2 delta = 1.0 / iResolution.xy;
    vec3 col = vec3(0.0, 0.0, 0.0);
    for(int i = 0; i < 3; i++)
    {
        for(int j = 0; j < 3; j++)
        {

            vec2 sampleCoordinate = uv + float(j == 0) * vec2(-delta.x, 0) + float(j == 2) * vec2(delta.x, 0);
            sampleCoordinate = sampleCoordinate + float(i == 0) * vec2(-delta.y, 0) + float(i == 2) * vec2(delta.y, 0);
            col += texture(iChannel0, sampleCoordinate).rgb * imageKernel[i][j];
        }
    }

    fragColor = vec4(col, 1.0);
}
